//
// Both keep one independent state per key, lazily created the first time
// that key reaches the policy.

export class TokenBucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity // BigInt
    this.refill = refill // BigInt
    this.per = per // BigInt
    // key -> { tokensNum: BigInt (tokens * per), lastTick: BigInt }
    this.states = new Map()
  }

  _get(key) {
    let st = this.states.get(key)
    if (!st) {
      st = { tokensNum: this.capacity * this.per, lastTick: null }
      this.states.set(key, st)
    }
    return st
  }

  advance(key, tick) {
    const st = this._get(key)
    if (st.lastTick === null) {
      st.lastTick = tick
      return
    }
    const delta = tick - st.lastTick
    if (delta > 0n) {
      const max = this.capacity * this.per
      let next = st.tokensNum + this.refill * delta
      if (next > max) next = max
      st.tokensNum = next
      st.lastTick = tick
    }
  }

  allow(key) {
    const st = this._get(key)
    return st.tokensNum >= this.per
  }

  record(key) {
    const st = this._get(key)
    st.tokensNum -= this.per
  }
}

export class SlidingWindow {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit // BigInt
    this.span = span // BigInt
    // key -> array of remembered ticks (BigInt), ascending
    this.states = new Map()
  }

  _get(key) {
    let st = this.states.get(key)
    if (!st) {
      st = []
      this.states.set(key, st)
    }
    return st
  }

  advance(key, tick) {
    const st = this._get(key)
    const cutoff = tick - this.span
    let i = 0
    while (i < st.length && st[i] <= cutoff) i++
    if (i > 0) st.splice(0, i)
  }

  allow(key) {
    const st = this._get(key)
    return BigInt(st.length) < this.limit
  }

  record(key, tick) {
    const st = this._get(key)
    st.push(tick)
  }
}
"}

