{"file_path":"src/validate.js","content":"// Shared lexical and numeric validation helpers.

export const NAME_RE = /^[A-Za-z0-9_./:-]+$/
export const INT_RE = /^(0|[1-9][0-9]*)$/

export function isValidName(s) {
  return NAME_RE.test(s)
}

export function fail(lineNo, reason) {
  const err = new Error(`line ${lineNo}: ${reason}`)
  err.isSimError = true
  throw err
}

// Parses an unsigned decimal integer field, enforcing the minimum. Returns a
// BigInt on success or throws a formatted line error.
export function parseField(lineNo, field, str, min) {
  if (!INT_RE.test(str) || BigInt(str) < BigInt(min)) {
    fail(lineNo, `${field} must be an integer of at least ${min}`)
  }
  return BigInt(str)
}
"}

