// on any violation of the specification.

import { isValidName, parseField, fail } from './validate.js'
import { TokenBucket, SlidingWindow } from './policies.js'

export function runLimiter(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map() // name -> instance (TokenBucket | SlidingWindow)
  const routes = new Map() // prefix -> [policyName, ...]
  let declEnded = false
  let lastTick = null // BigInt

  const events = []
  const summary = new Map() // key -> { allowed, denied }

  function summaryFor(key) {
    let s = summary.get(key)
    if (!s) {
      s = { allowed: 0, denied: 0 }
      summary.set(key, s)
    }
    return s
  }

  function findRoute(key) {
    let best = null
    for (const [prefix, names] of routes) {
      if (key.startsWith(prefix)) {
        if (best === null || prefix.length > best.prefix.length) {
          best = { prefix, names }
        }
      }
    }
    return best
  }

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i].trim()
    if (raw === '' || raw.startsWith('#')) continue
    const tokens = raw.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket') {
      if (declEnded) fail(lineNo, 'declarations must come before the first event')
      if (tokens.length !== 5) fail(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capStr, refillStr, perStr] = tokens
      if (!isValidName(name)) fail(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      const capacity = parseField(lineNo, 'capacity', capStr, 1)
      const refill = parseField(lineNo, 'refill', refillStr, 0)
      const per = parseField(lineNo, 'per', perStr, 1)
      policies.set(name, new TokenBucket(name, capacity, refill, per))
    } else if (directive === 'window') {
      if (declEnded) fail(lineNo, 'declarations must come before the first event')
      if (tokens.length !== 4) fail(lineNo, 'expected window <name> <limit> <span>')
      const [, name, limitStr, spanStr] = tokens
      if (!isValidName(name)) fail(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      const limit = parseField(lineNo, 'limit', limitStr, 0)
      const span = parseField(lineNo, 'span', spanStr, 1)
      policies.set(name, new SlidingWindow(name, limit, span))
    } else if (directive === 'route') {
      if (declEnded) fail(lineNo, 'declarations must come before the first event')
      if (tokens.length < 3) fail(lineNo, 'expected route <prefix> <policy>...')
      const prefix = tokens[1]
      const policyNames = tokens.slice(2)
      if (!isValidName(prefix)) fail(lineNo, `invalid route prefix ${prefix}`)
      if (routes.has(prefix)) fail(lineNo, `prefix ${prefix} is routed twice`)
      for (const name of policyNames) {
        if (!policies.has(name)) fail(lineNo, `unknown policy ${name}`)
      }
      routes.set(prefix, policyNames)
    } else if (directive === 'event') {
      if (tokens.length !== 3) fail(lineNo, 'expected event <tick> <key>')
      const [, tickStr, key] = tokens
      const tick = parseField(lineNo, 'tick', tickStr, 0)
      if (!isValidName(key)) fail(lineNo, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        fail(lineNo, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      declEnded = true

      const route = findRoute(key)
      let allowed = true
      let deniedBy = null

      if (route) {
        for (const name of route.names) {
          policies.get(name).advance(key, tick)
        }
        for (const name of route.names) {
          if (!policies.get(name).allow(key)) {
            allowed = false
            deniedBy = name
            break
          }
        }
        if (allowed) {
          for (const name of route.names) {
            const policy = policies.get(name)
            if (policy instanceof SlidingWindow) policy.record(key, tick)
            else policy.record(key)
          }
        }
      }

      const s = summaryFor(key)
      if (allowed) s.allowed++
      else s.denied++

      events.push({ tick: tick.toString(), key, allowed, deniedBy })
    } else {
      fail(lineNo, `unknown directive ${directive}`)
    }
  }

  return { events, summary }
}
"}

